css:
#loader-33 {
  width: 16px;
  aspect-ratio: 1;
  background: #3FB8AF;
  position: relative;
  animation: l5-0 2s infinite linear;
}
#loader-33:before {
  content: "";
  position: absolute;
  inset: 0;
  background: #FF3D7F;
  transform: translate(30px) rotate(0);
  animation: l5-1 .5s infinite 
}
@keyframes l5-0 {
   100% {transform: rotate(1turn)}
}
@keyframes l5-1 {
   100% {transform: translate(30px) rotate(.25turn)}
}
